"""Independent re-derivation of the replay semantics, written separately."""
import json, sys

def run(req):
    inputs = req["inputs"]
    P = len(inputs); R = len(inputs[0]) if P else 0
    D = len(inputs[0][0]) if (P and R) else 0
    NS = req["slots"]; W = req["window"]
    sent = [0]*P; recv = [[] for _ in range(P)]
    floor = 0; upnext = [0]*P; acked = [0]*P
    buf = {}          # seq -> {"ranks": set, "sum": list}
    pending = {}      # id -> packet
    nxt = 0
    log = []
    def mk(kind, rank, seq, value):
        nonlocal nxt
        pid = nxt; nxt += 1
        pending[pid] = {"id":pid,"kind":kind,"rank":rank,"seq":seq,"value":value}
        return pid
    for ev in req["events"]:
        k = ev[0]; made = []
        if k == "send":
            r, q = ev[1], ev[2]
            if sent[r] <= q and q < min(R, sent[r]+W):
                made.append(mk("up", r, q, list(inputs[r][q])))
                st = "ok"
            else:
                st = "disabled"
        elif k == "retry":
            r = ev[1]
            cands = sorted([s for s,e in buf.items() if len(e["ranks"])==P and s >= acked[r]])
            for s in cands:
                made.append(mk("down", r, s, list(buf[s]["sum"])))
            st = "ok"
        elif k == "drop":
            if ev[1] in pending:
                del pending[ev[1]]; st = "ok"
            else: st = "missing"
        elif k == "duplicate":
            if ev[1] in pending:
                p = pending[ev[1]]
                v = None if p["value"] is None else list(p["value"])
                made.append(mk(p["kind"], p["rank"], p["seq"], v)); st = "ok"
            else: st = "missing"
        elif k == "deliver":
            if ev[1] not in pending:
                st = "missing"
            else:
                p = pending.pop(ev[1])
                kind, r, s, v = p["kind"], p["rank"], p["seq"], p["value"]
                if kind == "up":
                    if floor <= s < floor+NS:
                        if s not in buf:
                            buf[s] = {"ranks":set(),"sum":[0]*D}
                        e = buf[s]
                        before = len(e["ranks"])==P
                        if r not in e["ranks"]:
                            e["ranks"].add(r)
                            e["sum"] = [a+b for a,b in zip(e["sum"],v)]
                        after = len(e["ranks"])==P
                        while True:
                            nxtseq = upnext[r]
                            if nxtseq in buf and r in buf[nxtseq]["ranks"]:
                                upnext[r] = nxtseq+1
                            else:
                                break
                        made.append(mk("uack", r, upnext[r], None))
                        if after and not before:
                            for rr in range(P):
                                made.append(mk("down", rr, s, list(e["sum"])))
                    else:
                        made.append(mk("uack", r, upnext[r], None))
                elif kind == "uack":
                    sent[r] = max(sent[r], s)
                elif kind == "down":
                    if s == len(recv[r]):
                        recv[r].append(list(v))
                    made.append(mk("dack", r, len(recv[r]), None))
                else:
                    acked[r] = max(acked[r], s)
                    floor = min(acked)
                    for sq in list(buf):
                        if sq < floor:
                            del buf[sq]
                st = "ok"
        log.append({"status":st,"created":made})
    return {
        "hosts":[{"sent":sent[r],"received":recv[r]} for r in range(P)],
        "floor":floor,
        "slots":[{"seq":s,"ranks":sorted(buf[s]["ranks"]),"sum":list(buf[s]["sum"])} for s in sorted(buf)],
        "packets":[pending[i] for i in sorted(pending)],
        "events":log,
    }

if __name__ == "__main__":
    for line in open(sys.argv[1]):
        req = json.loads(line)
        if req.get("op") != "replay": continue
        print(json.dumps(run(req), sort_keys=True))
